sys_variable_value.value:
(function execute(inputs, outputs) {
    // checked = Xero answered 200, so found can be trusted.
    // found = Xero has an entry for this user/task/day that is NOT yet linked
    // to any day in Xero Time Entry Sync (entries of other time cards are ignored).
    outputs.checked = false;
    outputs.found = false;
    outputs.time_entry_id = '';

    if ((inputs.status_code + '') != '200') {
        return;
    }
    var body = {};
    try {
        body = JSON.parse(inputs.response_body || '{}');
    } catch (e) {
        return;
    }
    outputs.checked = true;

    var items = body.items || [];
    for (var i = 0; i < items.length; i++) {
        var id = (items[i].timeEntryId || '') + '';
        if (!id) {
            continue;
        }
        var known = new GlideRecord('x_snc_spm_xero_i_0_xero_time_entry_sync');
        known.addQuery('xero_time_entry_id', id);
        known.setLimit(1);
        known.query();
        if (!known.hasNext()) {
            outputs.found = true;
            outputs.time_entry_id = id;
            return;
        }
    }
})(inputs, outputs);

